#if APP_TESTS
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Threading;
namespace FileCompass {
 internal static class PinnedTabsTests {
  internal static int Run(string root){Directory.CreateDirectory(root);var log=new List<string>();MainWindow window=null;string motif=AppearanceTheme.Motif;Action<bool,string> check=(yes,text)=>{if(!yes)throw new Exception(text);log.Add(text);};try{SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(Dispatcher.CurrentDispatcher));L.ChangeLanguage("cs");FluentTheme.Ensure();AppearanceTheme.Apply("Light");var home=Directory.CreateDirectory(Path.Combine(root,"Dokumenty")).FullName;var child=Directory.CreateDirectory(Path.Combine(home,"Faktury")).FullName;File.WriteAllText(Path.Combine(home,"ukázka.txt"),"sample");
   foreach(string theme in new[]{"Original","Balanced"}){AppearanceTheme.SetMotif(theme);var settings=new ProgramSettings{LeftFolder=home,RightFolder=home,SaveTabsOnExit=true};settings.Save();window=new MainWindow(null,settings){Left=-18000,Top=-18000,ShowActivated=false,WindowStartupLocation=WindowStartupLocation.Manual};window.Show();NavigationTests.WaitPanels(window);window.UpdateLayout();var panels=FluentUiTests.Children<FilePanel>(window).ToArray();var left=panels[0];
    check(FluentUiTests.Children<Button>(left).Any(x=>(x.Content as string)=="+"&&x.IsVisible),theme+": new-tab action is visible with one tab");
    left.PinCurrentFolder();check(left.TabCount==2&&left.SaveTabs()[1].Locked&&left.SaveTabs()[1].Home==home,theme+": pin creates a stable home folder tab");var persisted=ProgramSettings.Load();check(persisted.SaveTabsOnExit&&persisted.LeftTabs.Length==2&&persisted.LeftTabs[1].Locked,theme+": pin saves tab state immediately");
    left.PinCurrentFolder();NavigationTests.Wait(left.TabNavigationTask);check(left.TabCount==2,theme+": repeated pin reuses existing pinned tab");left.Navigate(child,true);NavigationTests.Wait(left.NavigationTask);left.SwitchTab(0);NavigationTests.Wait(left.TabNavigationTask);left.SwitchTab(1);NavigationTests.Wait(left.TabNavigationTask);check(left.CurrentPath==home,theme+": pinned tab returns to home after browsing a child");window.UpdateLayout();NextStageTests.Draw(window,Path.Combine(root,theme+"-tabs.png"));
    window.Close();window=null;settings=ProgramSettings.Load();window=new MainWindow(null,settings){Left=-18000,Top=-18000,ShowActivated=false,WindowStartupLocation=WindowStartupLocation.Manual};window.Show();NavigationTests.WaitPanels(window);left=FluentUiTests.Children<FilePanel>(window).First();check(left.TabCount==2&&left.CurrentPath==home&&left.SaveTabs()[1].Locked,theme+": pinned folders and active tab reopen after restart");


    left.LocalRowsForTests=(path,token)=>{throw new IOException("fixture disconnected",unchecked((int)0x80070035));};left.RestoreTabs(new[]{new SavedTab{Path=@"\\fixture.invalid\share",Home=@"\\fixture.invalid\share",Locked=true}},0);NavigationTests.Wait(left.NavigationTask);check(left.HasUnavailableTab&&left.UnavailableTabMessage.Contains(L.Text("tabs.unavailableDrive"))&&left.List.Items.Count==0,theme+": disconnected network drive has explicit status and no stale files");left.LocalRowsForTests=null;left.RestoreTabs(new[]{new SavedTab{Path=home}},0);NavigationTests.Wait(left.NavigationTask);
    string missing=Path.Combine(root,"missing-"+theme);left.RestoreTabs(new[]{new SavedTab{Path=home},new SavedTab{Path=missing,Home=missing,Locked=true,Label="Chybějící složka"}},1);NavigationTests.Wait(left.NavigationTask);check(left.HasUnavailableTab&&left.CurrentPath==null&&left.List.Items.Count==0,theme+": missing folder clears previous listing and shows unavailable state");check(left.SaveTabs()[1].Path==missing&&left.SaveTabs()[1].Home==missing,theme+": failed tab retains its original path");window.UpdateLayout();NextStageTests.Draw(window,Path.Combine(root,theme+"-missing-folder.png"));
    Directory.CreateDirectory(missing);left.SwitchTab(1);NavigationTests.Wait(left.TabNavigationTask);check(!left.HasUnavailableTab&&left.CurrentPath==missing,theme+": retry opens restored folder");
    left.RestoreTabs(new[]{new SavedTab{Path=home},new SavedTab{Path="/Media1",Home="/Media1",ProfileId="saved-ftp-fixture",Caption="FTP · KLADNO",Locked=true}},1);check(left.HasUnavailableTab&&!left.IsRemote&&left.SaveTabs()[1].ProfileId=="saved-ftp-fixture",theme+": restored FTP tab is disconnected without automatic login");left.SwitchTab(0);NavigationTests.Wait(left.TabNavigationTask);check(left.CurrentPath==home&&!left.HasUnavailableTab,theme+": valid tab can be selected after unavailable FTP tab");
    left.RestoreTabs(new[]{new SavedTab{Path=home},new SavedTab{Path="/Media1",Home="/Media1",ProfileId="saved-ftp-fixture",Caption="FTP · KLADNO",Locked=true}},1);window.UpdateLayout();NextStageTests.Draw(window,Path.Combine(root,theme+"-disconnected-ftp.png"));
    left.CloseTab(1);NavigationTests.Wait(left.TabNavigationTask);check(left.CurrentPath==home&&left.SaveTabs()[0].Path==home,theme+": closing failed tab preserves the remaining target");
    window.Close();window=null;persisted=ProgramSettings.Load();check(persisted.LeftTabs.Length==1&&persisted.LeftTabs[0].Path==home,theme+": tab removal persists through exit");
    var offline=new ProgramSettings{LeftFolder=home,RightFolder=home,SaveTabsOnExit=true,LeftTabs=new[]{new SavedTab{Path="/remote",Home="/remote",ProfileId="saved-ftp-fixture",Caption="FTP · KLADNO",Locked=true}}};offline.Save();window=new MainWindow(null,offline){Left=-18000,Top=-18000,ShowActivated=false,WindowStartupLocation=WindowStartupLocation.Manual};window.Show();NavigationTests.WaitPanels(window);left=FluentUiTests.Children<FilePanel>(window).First();check(left.HasUnavailableTab&&left.SaveTabs()[0].Path=="/remote",theme+": startup fallback does not replace disconnected remote tab");window.Close();window=null;
   }
   File.WriteAllLines(Path.Combine(root,"result.txt"),log.Concat(new[]{"PASS: "+log.Count+" checks"}));return 0;
  }catch(Exception ex){File.WriteAllLines(Path.Combine(root,"result.txt"),log.Concat(new[]{"FAIL: "+ex}));return 1;}finally{if(window!=null)window.Close();AppearanceTheme.SetMotif(motif);}}
 }
}
#endif
